/* ---- Filesystem Data ---- */
const FILESYSTEM = {
    '/': [
        'bin', 'etc', 'home', 'usr', 'var'
    ],
    '/bin': ['bash', 'ls', 'cat'],
    '/etc': ['passwd', 'hosts', 'resolv.conf'],
    '/home': ['user'],
    '/home/user': [
        'Documents', 'Downloads', 'Pictures', 'Desktop', '.bashrc'
    ],
    '/home/user/Documents': ['notes.txt', 'readme.md'],
    '/home/user/Downloads': ['install.sh', 'setup.py'],
    '/home/user/Pictures': ['vacation.jpg', 'profile.png'],
    '/home/user/Desktop': ['launcher.desktop'],
    '/usr': ['bin', 'lib', 'share'],
    '/usr/bin': ['python3', 'node', 'git', 'docker'],
    '/usr/lib': ['libc.so.6', 'libstdc++.so.6'],
    '/usr/share': ['man', 'doc'],
    '/var': ['log', 'cache', 'tmp'],
    '/var/log': ['syslog', 'auth.log'],
    '/var/cache': ['apt', 'dpkg'],
};

function getEntries(path) {
    const parts = path.split('/').filter(Boolean);
    let current = FILESYSTEM;
    for (const part of parts) {
        if (!current[part]) return [];
        current = current[part];
    }
    return Array.isArray(current) ? current : [];
}

function getEntryType(path, name) {
    const full = path + '/' + name;
    return FILESYSTEM[full] !== undefined ? 'folder' : 'file';
}

/* ---- Utility: Window positioning ---- */
let winIdCounter = 0;
const openWindows = {}; // id -> element

function placeWindow(winEl) {
    const w = winEl.offsetWidth || 380;
    const h = winEl.offsetHeight || 260;
    let x = 100 + (winIdCounter * 40);
    let y = 60 + (winIdCounter * 35);
    // keep in viewport
    if (x + w > window.innerWidth) x = Math.max(0, window.innerWidth - w - 20);
    if (y + h > window.innerHeight) y = Math.max(0, window.innerHeight - h - 20);
    winEl.style.left = x + 'px';
    winEl.style.top = y + 'px';
}

function openWindow(winId) {
    const el = document.getElementById(winId);
    if (!el) return;
    el.classList.add('open');
    placeWindow(el);
}

/* ---- Files App Logic ---- */
const filesPathEl = document.getElementById('files-path');
const filesListEl = document.getElementById('files-list');
let currentPath = '/';

function renderFiles() {
    const entries = getEntries(currentPath);
    filesListEl.innerHTML = '';
    for (const name of entries) {
        const type = getEntryType(currentPath, name);
        const item = document.createElement('div');
        item.className = 'fs-item';
        if (type === 'folder') {
            item.textContent = name + '/';
        } else {
            item.textContent = name;
        }
        item.addEventListener('dblclick', () => {
            if (type === 'folder') navigateTo(currentPath + '/' + name);
        });
        filesListEl.appendChild(item);
    }
}

function navigateTo(path) {
    currentPath = path.endsWith('/') ? path : path + '/';
    filesPathEl.textContent = currentPath;
    renderFiles();
}

document.getElementById('files-up').addEventListener('click', () => {
    if (currentPath === '/') return;
    const parts = currentPath.split('/').filter(Boolean);
    parts.pop();
    navigateTo(parts.length ? '/' + parts.join('/') : '/');
});

/* ---- Notepad App Logic ---- */
function loadTabsFromStorage() {
    try {
        const raw = localStorage.getItem('notepad-tabs');
        if (!raw) return [];
        return JSON.parse(raw);
    } catch { return []; }
}

function saveTabsToStorage(tabs) {
    try {
        localStorage.setItem('notepad-tabs', JSON.stringify(tabs));
    } catch {}
}

let tabCount = 0;
const tabsEl = document.getElementById('tabs');
const editorEl = document.getElementById('editor');

function createTab() {
    tabCount++;
    const id = 'tab-' + tabCount;
    const content = '';
    const label = 'New Tab';

    // persist
    addTabToStorage(label, content, id);

    const tabEl = document.createElement('div');
    tabEl.className = 'tab active';
    tabEl.dataset.id = id;
    tabEl.textContent = label;
    tabEl.addEventListener('click', () => switchTab(id));

    tabsEl.appendChild(tabEl);
    editorEl.value = content;
}

function addTabToStorage(label, content, id) {
    const existing = loadTabsFromStorage();
    existing.push({ id, label, content });
    saveTabsToStorage(existing);
}

function switchTab(id) {
    document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
    const tab = document.querySelector(`.tab[data-id="${id}"]`);
    if (tab) tab.classList.add('active');
    editorEl.value = getTabContent(id);
}

function setActiveEditor() {
    const active = tabsEl.querySelector('.tab.active');
    if (!active) return;
    const id = active.dataset.id;
    editorEl.value = getTabContent(id);
}

function getTabContent(id) {
    const existing = loadTabsFromStorage();
    return existing.find(t => t.id === id)?.content || '';
}

document.getElementById('new-tab').addEventListener('click', createTab);

