    if (!header) return;
    const winEl = header.parentElement;
    const rect = winEl.getBoundingClientRect();
    dragState = {
        winEl,
        startX: e.clientX - rect.left,
        startY: e.clientY - rect.top,
        initX: rect.left,
        initY: rect.top
    };
}

document.addEventListener('mousemove', (e) => {
    if (!dragState) return;
    const winEl = dragState.winEl;
    let x = dragState.initX + e.clientX - dragState.startX;
    let y = dragState.initY + e.clientY - dragState.startY;
    // bounds
