    winEl.style.top = y + 'px';
});

document.addEventListener('mouseup', () => { dragState = null; });


/* ---- Init: Restore tabs if notepad was open, then show files by default ---- */
(function init() {
    // Check if notepad has persisted tabs (e.g. from previous session)
    const savedTabs = loadTabsFromStorage();

    // Build the notepad window with its initial UI
    buildNotepadWindow(savedTabs);

    // Default: open files app on first visit
    setTimeout(() => {
        if (!document.getElementById('files-window').classList.contains('open') && !savedTabs.length) {
            openWindow('files-window');
        } else if (savedTabs.length) {
            openWindow('notepad-window');
        }
    }, 100);

})();

function buildNotepadWindow(savedTabs) {
    // Ensure #notepad-window exists in DOM
    let winEl = document.getElementById('notepad-window');
    if (!winEl) {
        winEl = document.createElement('div');
        winEl.id = 'notepad-window';
        winEl.className = 'window';
        winEl.innerHTML = `
            <div class="win-header">
                <span class="win-title"></span>
                <button class="win-close" onclick="closeWindow('notepad-window')">&times;</button>
            </div>
            <div id="tabs-bar">
                <div id="tabs"></div>
                <button id="new-tab">+ New Tab</button>
            </div>
            <div id="editor-container">
                <div class="editor-wrapper">
                    <textarea id="editor" placeholder="Type here..." spellcheck="false"></textarea>
                </div>
            </div>`;
        document.getElementById('desktop').appendChild(winEl);

        // Wire up events
        winEl.querySelector('.win-close').addEventListener('click', () => closeWindow('notepad-window'));
        editorEl = winEl.querySelector('#editor');
    } else {
        editorEl = winEl.querySelector('#editor');
    }

    // Restore tabs from storage — ensure at least one active tab exists
    if (savedTabs.length > 0) {
        for (const st of savedTabs) {
            const id = 'tab-' + (st.id.split('-').pop() || tabCount);
            createTab();
        }
        // Make sure first tab is active
        const first = tabsEl.querySelector('.tab');
        if (first) first.classList.add('active');
        editorEl.value = getTabContent(first.dataset.id);
    } else {
        createTab();
    }

    openWindow('notepad-window');
}

function closeWindow(winId) {
    const el = document.getElementById(winId);
    if (el) {
        el.classList.remove('open');
        setTimeout(() => {
            if (!document.getElementById(winId).classList.contains('open')) {
                el.style.display = 'none';
                // Remove from DOM after fade-out
                setTimeout(() => {
                    document.getElementById(winId)?.remove();
                }, 300);
            }
        }, 250);
    }
}

// Expose globally for inline onclick handlers
window.closeWindow = closeWindow;
window.openWindow = openWindow;
